      "ocr": "\u0dad\u0dca\u0dc0\u0dbb\u0dca \u0d85\u0db8\u0dca\u0dc0 \u0dc3\u0dd2\u0daf\u0dca\u0daf\u0dd4\u0dc0\u0dda \u0db4\u0dca\u0dbb\u0dd2\u0dba\u0dd4\u0daf\u0dca\u0db0 \u0dc3\u0dda \u0db4\u0dca\u0dbb\u0dd2\u0dba\u0dd4\u0daf\u0dca\u0db0 \u0dc3\u0dda\u0dc0 \u0dc3\u0dda\u0dc0 \u0dc3\u0dda\u0dc0 \u0dc3\u0dda\u0dc0 \u0dc3\u0dda\u0dc0 \u0dc3\u0dda\u0dc0 \u0dc3\u0dda\u0dc0 \u0dc3\u0dda\u0dc0 \u0dc3\u0dda\u0dc0 \u0dc3\u0dda\u0dc0",
